1	import type { Page, Locator } from '@playwright/test';
2	import { expect } from '@playwright/test';
3	
4	// Re-export test and expect from Playwright
5	export { test, expect } from '@playwright/test';
6	
7	// Re-export test utilities for convenience
8	export {
9	  clearAllStorage,
10	  waitForAutoSave,
11	  resetViewport,
12	  getNewestBin,
13	  getBinByIndex,
14	  getBinCount,
15	} from './test-utils';
16	
17	// Default timeout for wait operations (ms)
18	const DEFAULT_TIMEOUT = 5000;
19	
20	/**
21	 * Helper to get the grid canvas element.
22	 * The grid has role="application" and contains the drawer grid.
23	 */
24	export async function getGrid(page: Page): Promise<Locator> {
25	  return page.locator('[role="application"]');
26	}
27	
28	/**
29	 * Helper to wait for the app to be fully loaded.
30	 */
31	export async function waitForAppReady(page: Page) {
32	  await page.waitForSelector('header', { timeout: 10000 });
33	  // Wait for grid to be rendered
34	  await page.waitForSelector('[role="application"]', { timeout: 10000 });
35	}
36	
37	/**
38	 * Helper to get the grid bounds for mouse interactions.
39	 */
40	export async function getGridBounds(page: Page) {
41	  const grid = page.locator('[role="application"]');
42	  await grid.waitFor({ state: 'visible' });
43	  const bounds = await grid.boundingBox();
44	  if (!bounds) throw new Error('Grid not found');
45	  return bounds;
46	}
47	
48	// ============================================================================
49	// ROBUST WAIT HELPERS - Use these instead of waitForTimeout
50	// ============================================================================
51	
52	/**
53	 * Wait for a specific number of bins on the grid.
54	 */
55	export async function waitForBinCount(page: Page, count: number, timeout = DEFAULT_TIMEOUT) {
56	  await expect(page.locator('[data-bin-id]')).toHaveCount(count, { timeout });
57	}
58	
59	/**
60	 * Wait for a bin to be selected (aria-pressed="true").
61	 */
62	export async function waitForBinSelected(bin: Locator, timeout = DEFAULT_TIMEOUT) {
63	  await expect(bin).toHaveAttribute('aria-pressed', 'true', { timeout });
64	}
65	
66	/**
67	 * Wait for no bins to be selected.
68	 */
69	export async function waitForNoSelection(page: Page, timeout = DEFAULT_TIMEOUT) {
70	  // Wait until no bin has aria-pressed="true"
71	  await expect(page.locator('[data-bin-id][aria-pressed="true"]')).toHaveCount(0, { timeout });
72	}
73	
74	/**
75	 * Wait for a specific number of bins to be selected.
76	 */
77	export async function waitForSelectionCount(page: Page, count: number, timeout = DEFAULT_TIMEOUT) {
78	  await expect(page.locator('[data-bin-id][aria-pressed="true"]')).toHaveCount(count, { timeout });
79	}
80	
81	/**
82	 * Wait for undo button to be enabled.
83	 */
84	export async function waitForUndoEnabled(page: Page, timeout = DEFAULT_TIMEOUT) {
85	  await expect(page.getByRole('button', { name: /undo/i })).toBeEnabled({ timeout });
86	}
87	
88	/**
89	 * Wait for undo button to be disabled.
90	 */
91	export async function waitForUndoDisabled(page: Page, timeout = DEFAULT_TIMEOUT) {
92	  await expect(page.getByRole('button', { name: /undo/i })).toBeDisabled({ timeout });
93	}
94	
95	/**
96	 * Wait for redo button to be enabled.
97	 */
98	export async function waitForRedoEnabled(page: Page, timeout = DEFAULT_TIMEOUT) {
99	  await expect(page.getByRole('button', { name: /redo/i })).toBeEnabled({ timeout });
100	}
101	
102	/**
103	 * Wait for redo button to be disabled.
104	 */
105	export async function waitForRedoDisabled(page: Page, timeout = DEFAULT_TIMEOUT) {
106	  await expect(page.getByRole('button', { name: /redo/i })).toBeDisabled({ timeout });
107	}
108	
109	/**
110	 * Wait for a toast message to appear.
111	 */
112	export async function waitForToast(page: Page, pattern: RegExp, timeout = DEFAULT_TIMEOUT) {
113	  await expect(page.getByText(pattern)).toBeVisible({ timeout });
114	}
115	
116	/**
117	 * Wait for a dialog to be visible.
118	 * Excludes the Labs drawer which is always in DOM with role="dialog".
119	 */
120	export async function waitForDialog(page: Page, timeout = DEFAULT_TIMEOUT) {
121	  // Exclude Labs drawer using :not() selector
122	  const dialog = page.locator('[role="dialog"]:not([aria-label="Labs experimental features"])');
123	  await expect(dialog).toBeVisible({ timeout });
124	}
125	
126	/**
127	 * Get the active dialog (excluding Labs drawer).
128	 * Uses :not() selector to exclude Labs drawer which has aria-label.
129	 */
130	export function getActiveDialog(page: Page): Locator {
131	  return page.locator('[role="dialog"]:not([aria-label="Labs experimental features"])');
132	}
133	
134	/**
135	 * Helper to close any lingering dialogs in afterEach cleanup.
136	 * Excludes the Labs drawer which is always in DOM.
137	 */
138	export async function closeDialogs(page: Page): Promise<void> {
139	  const dialogs = getActiveDialog(page);
140	  if ((await dialogs.count()) > 0) {
141	    await page.keyboard.press('Escape');
142	    await dialogs.waitFor({ state: 'detached', timeout: 1000 }).catch(() => {});
143	  }
144	}
145	
146	/**
147	 * Wait for dialog to close.
148	 * Excludes the Labs drawer which is always in DOM with role="dialog".
149	 */
150	export async function waitForDialogClosed(page: Page, timeout = DEFAULT_TIMEOUT) {
151	  // Exclude Labs drawer using :not() selector
152	  const dialog = page.locator('[role="dialog"]:not([aria-label="Labs experimental features"])');
153	  await expect(dialog).not.toBeVisible({ timeout });
154	}
155	
156	/**
157	 * Wait for stash container to be visible (has bins).
158	 */
159	export async function waitForStashVisible(page: Page, timeout = DEFAULT_TIMEOUT) {
160	  await expect(page.locator('[data-staging-bin-id]').first()).toBeVisible({ timeout });
161	}
162	
163	/**
164	 * Wait for stash to be empty/hidden.
165	 */
166	export async function waitForStashHidden(page: Page, timeout = DEFAULT_TIMEOUT) {
167	  await expect(page.locator('[data-staging-bin-id]')).toHaveCount(0, { timeout });
168	}
169	
170	/**
171	 * Wait for staging bins count.
172	 */
173	export async function waitForStagingBinCount(page: Page, count: number, timeout = DEFAULT_TIMEOUT) {
174	  await expect(page.locator('[data-staging-bin-id]')).toHaveCount(count, { timeout });
175	}
176	
177	/**
178	 * Wait for paint mode indicator to be visible.
179	 */
180	export async function waitForPaintMode(
181	  page: Page,
182	  width: number,
183	  depth: number,
184	  timeout = DEFAULT_TIMEOUT
185	) {
186	  await expect(page.getByText(new RegExp(`paint.*${width}×${depth}`, 'i'))).toBeVisible({
187	    timeout,
188	  });
189	}
190	
191	/**
192	 * Wait for paint mode to be exited.
193	 * Looks for the paint mode button (with aria-label="Exit paint mode") to not be visible.
194	 */
195	export async function waitForPaintModeExited(page: Page, timeout = DEFAULT_TIMEOUT) {
196	  await expect(page.getByRole('button', { name: 'Exit paint mode' })).not.toBeVisible({ timeout });
197	}
198	
199	/**
200	 * Wait for canvas (3D preview) to be visible.
201	 */
202	export async function waitForCanvas(page: Page, timeout = 10000) {
203	  await expect(page.locator('canvas').first()).toBeVisible({ timeout });
204	}
205	
206	/**
207	 * Wait for canvas (3D preview) to be hidden.
208	 */
209	export async function waitForCanvasHidden(page: Page, timeout = DEFAULT_TIMEOUT) {
210	  await expect(page.locator('canvas')).not.toBeVisible({ timeout });
211	}
212	
213	// ============================================================================
214	// IMPROVED INTERACTION HELPERS
215	// ============================================================================
216	
217	/**
218	 * Helper to draw a bin on the grid by dragging.
219	 * Returns the bin locator for the newly created bin.
220	 */
221	export async function drawBinOnGrid(
222	  page: Page,
223	  startX: number,
224	  startY: number,
225	  endX: number,
226	  endY: number
227	): Promise<Locator> {
228	  const countBefore = await page.locator('[data-bin-id]').count();
229	  const bounds = await getGridBounds(page);
230	
231	  await page.mouse.move(bounds.x + startX, bounds.y + startY);
232	  await page.mouse.down();
233	  await page.mouse.move(bounds.x + endX, bounds.y + endY, { steps: 5 });
234	  await page.mouse.up();
235	
236	  // Wait for bin count to increase
237	  await waitForBinCount(page, countBefore + 1);
238	
239	  // Return the newest bin (more explicit than .last())
240	  const { getNewestBin } = await import('./test-utils');
241	  return getNewestBin(page);
242	}
243	
244	/**
245	 * Helper to select a bin at a position and verify selection.
246	 */
247	export async function selectBinAt(page: Page, x: number, y: number) {
248	  const bounds = await getGridBounds(page);
249	  await page.mouse.click(bounds.x + x, bounds.y + y);
250	
251	  // Wait for at least one bin to be selected
252	  await expect(page.locator('[data-bin-id][aria-pressed="true"]').first()).toBeVisible({
253	    timeout: DEFAULT_TIMEOUT,
254	  });
255	}
256	
257	/**
258	 * Helper to count bins displayed on the grid.
259	 */
260	export async function countBins(page: Page): Promise<number> {
261	  const bins = page.locator('[data-bin-id]');
262	  return bins.count();
263	}
264	
265	/**
266	 * Helper to select a bin size from the palette.
267	 */
