cat > /tmp/full-flow.js <<'EOF'
async (page) => {
  const out = {};
  await page.goto('http://[::1]:5174/');
  await page.waitForSelector('header');
  await page.waitForSelector('[role="application"]');
  const grid = page.locator('[role="application"]');
  const summary = page.locator('[data-sidebar]').getByText(/% filled/);
  out.urlAfterGoto = page.url();
  out.gridName = await grid.getAttribute('aria-label');
  out.binsBefore = await page.locator('[data-bin-id]').count();
  out.summaryBefore = await summary.textContent();
  out.emptyList = await page.locator('[data-inspector]').getByText('No bins to print').count();
  // anything overlaying the grid (onboarding)?
  out.dialogs = await page.locator('[role="dialog"]:not([aria-label="Labs experimental features"])').count();

  const box = await grid.boundingBox();
  const cw = box.width / 10, ch = box.height / 8;
  await page.mouse.move(box.x + cw * 0.5, box.y + ch * 0.5);
  await page.mouse.down();
  await page.mouse.move(box.x + cw * 1.5, box.y + ch * 1.5, { steps: 8 });
  await page.mouse.up();
  await page.waitForTimeout(1000);

  out.binsAfter = await page.locator('[data-bin-id]').count();
  const bin = grid.getByRole('button', { name: 'Bin 2 by 2, category Coral' });
  out.binVisible = await bin.isVisible();
  const bb = await bin.boundingBox();
  out.geom = { box, cw, ch, bb,
    centerDX: (bb.x + bb.width / 2) - (box.x + cw),
    centerDY: (bb.y + bb.height / 2) - (box.y + ch),
    dW: bb.width - 2 * cw, dH: bb.height - 2 * ch };
  out.summaryAfter = await summary.textContent();
  out.listTotal = await page.locator('[data-inspector]').getByText(/^\d+ bins$/).textContent();
  out.qtyCell = await page.locator('[data-inspector] table tbody tr td').nth(2).textContent();
  out.sizeCell = await page.locator('[data-inspector] table tbody tr td').nth(0).innerText();

  // persistence: wait for save then reload
  await page.waitForTimeout(2500);
  await page.reload();
  await page.waitForSelector('[role="application"]');
  await page.waitForTimeout(1200);
  out.urlAfterReload = page.url();
  out.binsAfterReload = await page.locator('[data-bin-id]').count();
  out.binVisibleAfterReload = await grid.getByRole('button', { name: 'Bin 2 by 2, category Coral' }).isVisible();
  out.summaryAfterReload = await summary.textContent();
  return JSON.stringify(out, null, 1);
}
EOF
