async (page) => {
  const out = { runs: [] };
  const grid = page.locator('[role="application"]');
  for (let i = 0; i < 3; i++) {
    await page.evaluate(async () => {
      localStorage.clear(); sessionStorage.clear();
      const dbs = await indexedDB.databases();
      await Promise.all(dbs.map(d => new Promise((res) => {
        const r = indexedDB.deleteDatabase(d.name); r.onsuccess = r.onerror = r.onblocked = () => res();
      })));
    });
    await page.goto('http://[::1]:5174/');
    await page.waitForSelector('[role="application"]');
    await page.waitForTimeout(800);
    const before = await grid.boundingBox();
    const cw0 = before.width / 10, ch0 = before.height / 8;
    await page.mouse.move(before.x + cw0 * 0.5, before.y + ch0 * 0.5);
    await page.mouse.down();
    await page.mouse.move(before.x + cw0 * 1.5, before.y + ch0 * 1.5, { steps: 8 });
    await page.mouse.up();
    await page.waitForTimeout(900);
    const after = await grid.boundingBox();
    const cw = after.width / 10, ch = after.height / 8;
    const bin = grid.getByRole('button', { name: 'Bin 2 by 2, category Coral' });
    const bb = await bin.boundingBox();
    out.runs.push({
      count: await page.locator('[data-bin-id]').count(),
      gridArea: await page.locator('[data-bin-id]').first().evaluate(e => getComputedStyle(e).gridArea),
      beforeX: before.x, afterX: after.x, cw, ch,
      centerDX: (bb.x + bb.width / 2) - (after.x + cw),
      centerDY: (bb.y + bb.height / 2) - (after.y + ch),
      dW: bb.width - 2 * cw, dH: bb.height - 2 * ch,
      containedX: bb.x >= after.x - 2 && bb.x + bb.width <= after.x + after.width + 2,
      containedY: bb.y >= after.y - 2 && bb.y + bb.height <= after.y + after.height + 2,
      summary: await page.locator('[data-sidebar]').getByText(/% filled/).textContent(),
    });
  }
  return JSON.stringify(out, null, 1);
}
EOF
